SQL:
SELECT DISTINCT language
FROM foreign_data
WHERE id::numeric > 0;

SELECT COUNT(*)::numeric
FROM set_translations
WHERE language = 'French';

SELECT COUNT(*)::numeric
FROM cards
WHERE bordercolor = 'gold';

SELECT AVG(convertedmanacost)::numeric AS avg_cost
FROM cards
WHERE colors = 'G';

SELECT AVG(totalsetsize)::numeric AS avg_total
FROM sets
WHERE releasedate >= '2015-01-01'::date;

SELECT COUNT(*)::numeric AS count_cards
FROM cards
WHERE colors = 'U';

SELECT MAX(convertedmanacost)::numeric AS max_cmc
FROM cards
WHERE bordercolor = 'borderless';

SELECT DISTINCT language
FROM foreign_data
ORDER BY language;

SELECT COUNT(*)::numeric AS promo_sets
FROM sets
WHERE type = 'promo';

SELECT COUNT(*)::numeric AS paper_available
FROM cards
WHERE availability LIKE '%paper%';

SELECT DISTINCT rarity
FROM cards
ORDER BY rarity;

SELECT COUNT(*)::numeric AS thb_translations
FROM set_translations
WHERE setcode = 'THB';

SELECT (100.0 * SUM(CASE WHEN hasfoil = 1 THEN 1 ELSE 0 END)::numeric / NULLIF(COUNT(*)::numeric, 0)) AS foil_percentage
FROM cards
WHERE setcode = 'MB1';

SELECT COUNT(*)::numeric AS mythic_count
FROM cards
WHERE rarity = 'mythic';

SELECT COUNT(*)::numeric AS foil_only_sets
FROM sets
WHERE isfoilonly = 1;

SELECT COUNT(*)::numeric AS paper_only_cards
FROM cards
WHERE availability = 'paper';

SELECT DISTINCT NULLIF(format, '') AS format
FROM legalities
WHERE status = 'Banned';

SELECT COUNT(*)::numeric AS flying_cards
FROM cards
WHERE keywords = 'Flying';

SELECT NULLIF(COUNT(*)::numeric, 0) AS mythic_cards
FROM cards
WHERE rarity = 'mythic';

SELECT NULLIF(COUNT(*)::numeric, 0) AS french_translations_count
FROM set_translations
WHERE language = 'French';

SELECT DISTINCT NULLIF(language, '') AS language
FROM foreign_data
ORDER BY language;

SELECT COUNT(*)::numeric AS basic_cards
FROM cards
WHERE supertypes LIKE '%Basic%';

SELECT AVG(NULLIF(convertedmanacost, 0)::numeric) AS avg_cmc
FROM cards
WHERE coloridentity = 'G';

SELECT COUNT(*) AS promo_sets
FROM "sets"
WHERE "type" = 'promo';

SELECT COUNT(*) AS paper_available_cards
FROM "cards"
WHERE "availability" LIKE '%paper%';

SELECT DISTINCT "language"
FROM "set_translations"
ORDER BY "language";

SELECT COUNT(*) AS mythic_cards
FROM "cards"
WHERE "rarity" = 'mythic';

SELECT COUNT(*) AS promo_flagged_cards
FROM "cards"
WHERE "ispromo" = 1;
